def popcount(x):
    return bin(x).count("1")


def is_sorted_mask(n, m):
    """sorted iff 0^k 1^(n-k) with channel 0 first, channel c = bit c."""
    w = popcount(m)
    return m == (((1 << w) - 1) << (n - w))


def flatten(layers):
    return [tuple(c) for L in layers for c in L]


def outputs_bitparallel(n, comparators):
    """oracle path A: one big integer per channel, bit x = value of that channel on input x."""
    N = 1 << n
    ch = []
    for k in range(n):
        m = 0
        for x in range(N):
            if (x >> k) & 1:
                m |= 1 << x
        ch.append(m)
    for (i, j) in comparators:
        a, b = ch[i], ch[j]
        ch[i], ch[j] = a & b, a | b          # min to i, max to j
    out = []
    for x in range(N):
        v = 0
        for k in range(n):
            if (ch[k] >> x) & 1:
                v |= 1 << k
        out.append(v)
    return out


def outputs_scalar(n, comparators):
    """oracle path B: one input at a time, list of bits, sharing no code with path A."""
    res = []
    for x in range(1 << n):
        v = [(x >> k) & 1 for k in range(n)]
        for (i, j) in comparators:
            if v[i] > v[j]:
                v[i], v[j] = v[j], v[i]
        res.append(sum(b << k for k, b in enumerate(v)))
    return res


def reachable_multiset(n, comparators, both_paths=True):
    """mu_P as a Counter mask -> input mass. Two oracle paths asserted equal when both_paths."""
    a = outputs_bitparallel(n, comparators)
    if both_paths:
        b = outputs_scalar(n, comparators)
        assert a == b, "ORACLE DISAGREEMENT: the two paths differ -- do not trust any number here"
    return collections.Counter(a)


def V_direct(n, comparators):
    return sum(1 for m in outputs_bitparallel(n, comparators) if not is_sorted_mask(n, m))


def rc_dual(n, layers):
    """agent-0196's reverse-complement dual: [i,j] -> [n-1-j, n-1-i], layer order kept."""
    return [[(n - 1 - j, n - 1 - i) for (i, j) in L] for L in layers]


def multiset_hash(layers):
    return hashlib.md5(repr(sorted(tuple(sorted(c)) for L in layers for c in L)).encode()).hexdigest()[:12]


def harvest(datadir):
    """every published layered network at the two open cells, keyed by id, loaded from bytes."""
    found = {}
    for fn in sorted(os.listdir(datadir)):
        if not fn.endswith(".json"):
            continue
        try:
            with open(os.path.join(datadir, fn)) as fh:
                doc = json.load(fh)
        except Exception:
            continue

        def walk(node):
            if isinstance(node, dict):
                if "layers" in node and isinstance(node.get("layers"), list) and node.get("layers"):
                    L = node["layers"]
                    ok = all(isinstance(l, list) and all(isinstance(c, list) and len(c) == 2 for c in l) for l in L)
                    if ok:
                        n = node.get("n")
                        if n is None:
                            chans = [c for l in L for cc in l for c in cc]
                            n = max(chans) + 1 if chans else 0
                        wid = node.get("id") or "%s:%s" % (fn, multiset_hash(L))
                        size = sum(len(l) for l in L)
                        key = (n, len(L), size, multiset_hash(L))
                        if key not in found:
                            found[key] = {"id": wid, "file": fn, "n": n, "layers": [[tuple(c) for c in l] for l in L],
                                          "size": size, "depth": len(L), "V_declared": node.get("V")}
                for v in node.values():
                    walk(v)
            elif isinstance(node, list):
                for v in node:
                    walk(v)

        walk(doc)
    return found


